**Code à analyser** :
```javascript
function loginUser() {
    var username = document.getElementById('username').value;
    var password = document.getElementById('password').value;

    // Stockage des credentials
    localStorage.setItem('user_credentials', JSON.stringify({
        username: username,
        password: password,
        isAdmin: username === 'admin'
    }));

    // Validation côté client uniquement
    if (username === 'admin' && password === 'admin123') {
        document.innerHTML = '<h1>Bienvenue ' + username + '!</h1>';
        window.location = '/admin.html';
    }

    // Appel API sans validation
    eval('var userData = ' + localStorage.getItem('user_credentials'));
    fetch('/api/login', {
        method: 'POST',
        body: 'username=' + username + '&password=' + password
    });
}
```

**Vulnérabilités identifiées** :

## 1. XSS (Cross-Site Scripting)
**Problème** : `document.innerHTML = '<h1>Bienvenue ' + username + '!</h1>';`
**Exploit** : `username = "<script>alert('XSS')</script>"`
**Correction** :
```javascript
document.getElementById('welcome').textContent = 'Bienvenue ' + username + '!';
// OU
document.getElementById('welcome').innerHTML = 'Bienvenue ' + DOMPurify.sanitize(username) + '!';
```

## 2. Stockage non sécurisé des credentials
**Problème** : Mot de passe en clair dans localStorage
**Exploit** : Accès via dev tools ou XSS
**Correction** :
```javascript
// Ne jamais stocker les mots de passe
// Utiliser un token JWT après authentification
sessionStorage.setItem('auth_token', response.token);
```

## 3. Injection de Code (eval)
**Problème** : `eval('var userData = ' + localStorage.getItem('user_credentials'))`
**Exploit** : Manipulation du localStorage
**Correction** :
```javascript
try {
    var userData = JSON.parse(localStorage.getItem('user_credentials'));
} catch (e) {
    console.error('Invalid JSON data');
    userData = null;
}
```

## 4. Validation côté client uniquement
**Problème** : Logique d'authentification côté client
**Exploit** : Bypass via modification du code
**Correction** :
```javascript
// Déplacer la validation côté serveur
fetch('/api/login', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({username, password})
})
.then(response => response.json())
.then(data => {
    if (data.success) {
        sessionStorage.setItem('auth_token', data.token);
        window.location.href = data.redirect;
    }
});
```

## 5. CSRF (Cross-Site Request Forgery)
**Problème** : Pas de protection CSRF
**Correction** :
```javascript
// Ajouter un token CSRF
fetch('/api/login', {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]').content
    },
    body: JSON.stringify({username, password})
});
```

**Version corrigée complète** :
```javascript
async function loginUser() {
    const username = document.getElementById('username').value.trim();
    const password = document.getElementById('password').value;

    // Validation de base côté client
    if (!username || !password) {
        showError('Nom d\'utilisateur et mot de passe requis');
        return;
    }

    try {
        const response = await fetch('/api/login', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': getCSRFToken()
            },
            body: JSON.stringify({username, password})
        });

        const data = await response.json();

        if (data.success) {
            // Stockage sécurisé du token
            sessionStorage.setItem('auth_token', data.token);

            // Redirection sécurisée
            window.location.href = data.redirect || '/dashboard';
        } else {
            showError(data.message || 'Échec de connexion');
        }
    } catch (error) {
        console.error('Login error:', error);
        showError('Erreur de connexion');
    }
}

function showError(message) {
    const errorDiv = document.getElementById('error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
}

function getCSRFToken() {
    return document.querySelector('meta[name="csrf-token"]')?.content || '';
}
```
